// R4f-error E4 (transcript-09, WI-4): the 2.42304.0 error-card retry decision (cee72b629 d = `lz`) and what it reads —
// shared-104's transcript row scans, c06cf64bb's NON_RESENDABLE sentinel and c73f45bc3's retry nudge copy — generated by
// scripts/extract-retry-decision.mjs. Every outcome is driven by official message shapes (user / assistant / result rows
// of the session transcript); nothing here sends, renders or reads a real session.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { setLocale, DEFAULT_LOCALE, t as translate } from '../electron/i18n/index.mjs';
import { extractRetryDecision } from '../scripts/extract-retry-decision.mjs';
import { decideErrorRetry, rejectedDraftRetryState, lastTurnFailed, unansweredPromptUuid, conversationNotFound, REPEAT_PROMPT_WINDOW_MS }
  from '../src/generated/retry-decision/retry-decision.mjs';
import { lastTerminalRowIndex, pendingPromptUuid, isFailedTerminalRow, isTerminalRow, isHumanPromptRow } from '../src/generated/retry-decision/transcript-rows.mjs';
import { NON_RESENDABLE_REJECTION } from '../src/generated/retry-decision/non-resendable.mjs';
import { retryNudgeMessages, cannedNudges } from '../src/generated/retry-decision/retry-nudge-messages.mjs';

const app = path.resolve(import.meta.dirname, '..');
const generated = path.join(app, 'src/generated/retry-decision');
const reference = path.resolve(app, '../reference/installed-2.42304.0-20261017');
const official = name => fs.readFileSync(path.join(reference, 'ion-dist/assets/v1', name), 'utf8');
const count = (text, needle) => text.split(needle).length - 1;

// Official transcript rows (the SDK message stream a session bucket's `messages` snapshot holds).
const prompt = (uuid, text = 'Fix the failing test') => ({ type: 'user', uuid, message: { role: 'user', content: text } });
const reply = (uuid = 'a1') => ({ type: 'assistant', uuid, message: { role: 'assistant', content: [{ type: 'text', text: 'Working on it' }] } });
const toolResult = uuid => ({ type: 'user', uuid, message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'toolu_1', content: 'ok' }] } });
const success = () => ({ type: 'result', subtype: 'success', is_error: false, result: 'Done' });
const failure = (errors = ['Stream closed']) => ({ type: 'result', subtype: 'error_during_execution', is_error: true, errors });
const apiError = () => ({ type: 'assistant', uuid: 'a-err', isApiErrorMessage: true, message: { role: 'assistant', content: [{ type: 'text', text: 'API Error: 529' }] } });
// The decision input cee72b629 f (`sz`) builds from a bucket; fields not named take the store's defaults.
const bucket = fields => ({ error: null, errorKilledTurn: false, errorRejectedPrompt: null, heldInput: [], messages: [], desktopSession: true,
  conversationLost: false, lastPrompt: undefined, ...fields });
const EMPTY = { text: '', isEmpty: true };
const DRAFT = { text: 'one more thing', isEmpty: false };

test('E4 generator: the emitted originals are current, closed over this folder and pinned to the installed sources', async () => {
  const manifest = await extractRetryDecision({ check: true });
  assert.equal(manifest.referenceVersion, '2.42304.0');
  assert.equal(manifest.adapterModule, null);
  assert.deepEqual(manifest.modules.map(m => m.target), ['define-messages.mjs', 'logger.mjs', 'prompt-text.mjs', 'transcript-rows.mjs', 'non-resendable.mjs',
    'retry-nudge-messages.mjs', 'retry-decision.mjs']);
  for (const module of manifest.modules) for (const entry of module.imports) assert.equal(entry.kind, 'generated', `${module.target} ${entry.local}`);
  for (const name of fs.readdirSync(generated).filter(n => n.endsWith('.mjs'))) {
    const text = fs.readFileSync(path.join(generated, name), 'utf8');
    for (const [, from] of text.matchAll(/from "([^"]+)"/g)) assert.ok(from.startsWith('./'), `${name} imports ${from}`);
  }
  const decision = manifest.modules.find(m => m.target === 'retry-decision.mjs');
  assert.deepEqual(decision.bindings.map(b => b.name), ['s', 'c', 'l', 'u', 'd', 'h']);
  assert.deepEqual(decision.imports.map(i => [i.local, i.original]), [['r', 'Am'], ['e', 'sC'], ['t', 'oC'], ['n', 'lC']]);
  assert.ok(fs.existsSync(path.join(app, 'scripts/verify-gen-retry-decision.mjs')));
});

test('E4 official: lz, its outcome dispatch, the nudge send and the NON_RESENDABLE record in 2.42304.0', () => {
  const decision = official('cee72b629-k4HYmvQy.js');
  for (const text of ['export{m as a,h as i,f as n,o as r,d as t}', '"no conversation found with session id"', 'u=6e5',
    'return i&&!e.errorKilledTurn||e===void 0||!s(e.messages)?"focus":t.isEmpty?"nudge":"nudgeBesideDraft"'])
    assert.equal(count(decision, text), 1, text);
  assert.equal(count(decision, 'nudgeBesideDraft'), 2);
  const session = official('cc43287c9-DAfOi8yP.js');
  assert.equal(count(session, 'lz('), 3);
  for (const text of ['ct=be?.retryNudge===!0&&W.type==="local"', 'ct||fe(He,st)',
    'a==="nudge"?(Ro(),Eo(V.formatMessage(xN.retryNudge)),r.submit({retryNudge:!0,personSent:i}),!0)',
    'a==="nudgeBesideDraft"&&G?(y_(G,i),r.scheduleFocus(),!0)', 'handleErrorRetry:x_'])
    assert.equal(count(session, text), 1, text);
  assert.equal(count(official('c73f45bc3-CFrHin0p.js'), 'retryNudge:{defaultMessage:"Try again",id:"FazwRldA7z"}'), 1);
  assert.equal(count(official('c06cf64bb-BE5q2vSr.js'), 'Am=Symbol("NON_RESENDABLE_REJECTION")'), 1);
  assert.equal(count(official('c6b8adeaf-C5Aww7gq.js'), 'c!==!0&&L.getState().buckets[t.id]?.error===o&&f(t.id,kn,x)'), 1);
});

test('E4 resend / focus: a rejected prompt is resent only while it is still the composer text and resendable', () => {
  const rejected = bucket({ error: 'Message couldn’t be sent', errorRejectedPrompt: 'Fix the failing test' });
  assert.equal(decideErrorRetry(rejected, { text: 'Fix the failing test', isEmpty: false }), 'resend');
  assert.equal(decideErrorRetry(rejected, { text: 'Fix the failing test, please', isEmpty: false }), 'focus');
  assert.equal(decideErrorRetry(rejected, EMPTY), 'focus');
  // A failed send whose text is not the composer's records the sentinel: never resend, even for a matching string.
  const sentinel = bucket({ error: 'Message couldn’t be sent', errorRejectedPrompt: NON_RESENDABLE_REJECTION });
  assert.equal(typeof NON_RESENDABLE_REJECTION, 'symbol');
  assert.equal(NON_RESENDABLE_REJECTION.description, 'NON_RESENDABLE_REJECTION');
  assert.equal(decideErrorRetry(sentinel, { text: 'NON_RESENDABLE_REJECTION', isEmpty: false }), 'focus');
  // The rejected prompt only counts while an error is shown.
  assert.equal(decideErrorRetry(bucket({ errorRejectedPrompt: 'x', messages: [prompt('u1'), failure()], errorKilledTurn: true }), { text: 'x', isEmpty: false }), 'nudgeBesideDraft');
});

test('E4 rejectedDraftRetryState (`oz`): a restored draft from a session that never started resends its own text', () => {
  const state = rejectedDraftRetryState('Start the migration');
  assert.deepEqual(state, { error: '', errorKilledTurn: false, errorRejectedPrompt: 'Start the migration', heldInput: [], messages: [] });
  assert.equal(decideErrorRetry(state, { text: 'Start the migration', isEmpty: false }), 'resend');
  assert.equal(decideErrorRetry(state, { text: 'Something else', isEmpty: false }), 'focus');
  assert.equal(rejectedDraftRetryState(undefined), undefined);
  assert.equal(decideErrorRetry(rejectedDraftRetryState(undefined), EMPTY), 'focus');
});

test('E4 deliver: held input is delivered from an empty composer, otherwise focus', () => {
  const held = bucket({ heldInput: [{ uuid: 'h1', text: 'queued while parked' }], messages: [prompt('u1'), failure()], error: 'Turn failed', errorKilledTurn: true });
  assert.equal(decideErrorRetry(held, EMPTY), 'deliver');
  assert.equal(decideErrorRetry(held, DRAFT), 'focus');
});

test('E4 repeatPrompt / refillPrompt: a lost CLI conversation sends the last prompt again within 10 minutes, else puts it back', () => {
  const now = 1_800_000_000_000;
  assert.equal(REPEAT_PROMPT_WINDOW_MS, 600_000);
  const lost = sentAt => bucket({ error: 'No conversation found', errorKilledTurn: true, conversationLost: true,
    messages: [prompt('u0', 'Earlier'), reply('a0'), success(), prompt('u1'), failure()], lastPrompt: { uuid: 'u1', text: 'Fix the failing test', sentAt, whole: true } });
  assert.equal(decideErrorRetry(lost(now - 60_000), EMPTY, now), 'repeatPrompt');
  assert.equal(decideErrorRetry(lost(now - REPEAT_PROMPT_WINDOW_MS + 1), EMPTY, now), 'repeatPrompt');
  assert.equal(decideErrorRetry(lost(now - REPEAT_PROMPT_WINDOW_MS), EMPTY, now), 'refillPrompt');
  assert.equal(decideErrorRetry(lost(now - REPEAT_PROMPT_WINDOW_MS - 1), EMPTY, now), 'refillPrompt');
  assert.equal(decideErrorRetry(lost(now), EMPTY, now), 'repeatPrompt');
  assert.equal(decideErrorRetry(lost(now + 5_000), EMPTY, now), 'refillPrompt'); // a clock step backwards never repeats
  assert.equal(decideErrorRetry(lost(undefined), EMPTY, now), 'refillPrompt'); // no sentAt (NaN)
  assert.equal(decideErrorRetry({ ...lost(now - 60_000), lastPrompt: { uuid: 'u1', text: 'Fix', sentAt: now - 60_000, whole: false } }, EMPTY, now), 'refillPrompt');
  assert.equal(decideErrorRetry(lost(now - 60_000), DRAFT, now), 'focus');
  assert.equal(decideErrorRetry({ ...lost(now - 60_000), lastPrompt: undefined }, EMPTY, now), 'focus');
  assert.equal(decideErrorRetry({ ...lost(now - 60_000), lastPrompt: { uuid: 'u0', text: 'Earlier', sentAt: now - 60_000, whole: true } }, EMPTY, now), 'focus');
  // An assistant row after the prompt means the conversation answered: not the prompt to send again.
  const answered = { ...lost(now - 60_000), messages: [prompt('u1'), reply('a1'), failure()] };
  assert.equal(unansweredPromptUuid(answered.messages), undefined);
  assert.equal(decideErrorRetry(answered, EMPTY, now), 'focus');
  // The terminal row's own text also marks the loss (case-insensitive), without the shown category.
  const byText = bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), failure(['No conversation found with session ID 1234'])],
    lastPrompt: { uuid: 'u1', text: 'Fix the failing test', sentAt: now - 1_000, whole: true } });
  assert.equal(conversationNotFound(byText.messages), true);
  assert.equal(decideErrorRetry(byText, EMPTY, now), 'repeatPrompt');
  assert.equal(conversationNotFound([prompt('u1'), { ...success(), result: 'no conversation found with session id 9' }]), true);
  // Only a desktop session: a remote one falls through to the nudge rule.
  assert.equal(decideErrorRetry({ ...byText, desktopSession: false }, EMPTY, now), 'nudge');
});

test('E4 nudge / nudgeBesideDraft: a turn that died after the prompt reached it gets the short Try again, beside a draft', () => {
  const died = bucket({ error: 'Stream closed', errorKilledTurn: true, messages: [prompt('u1'), reply(), failure()] });
  assert.equal(decideErrorRetry(died, EMPTY), 'nudge');
  assert.equal(decideErrorRetry(died, DRAFT), 'nudgeBesideDraft');
  // No terminal row yet: the prompt still waits for its result.
  const midTurn = bucket({ error: 'Process exited', errorKilledTurn: true, messages: [prompt('u1'), reply()] });
  assert.equal(lastTerminalRowIndex(midTurn.messages), null);
  assert.equal(pendingPromptUuid(midTurn.messages), 'u1');
  assert.equal(decideErrorRetry(midTurn, EMPTY), 'nudge');
  // An API-error assistant row is a failed terminal row.
  const api = bucket({ error: 'Overloaded', errorKilledTurn: true, messages: [prompt('u1'), apiError()] });
  assert.equal(isTerminalRow(api.messages[1]), true);
  assert.equal(isFailedTerminalRow(api.messages[1]), true);
  assert.equal(decideErrorRetry(api, EMPTY), 'nudge');
  // A prompt after the last success is unanswered.
  assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), success(), prompt('u2')] }), EMPTY), 'nudge');
  // Subagent rows (parent_tool_use_id) never count as the session's terminal row.
  const sub = bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), failure(), { ...success(), parent_tool_use_id: 'toolu_9' }] });
  assert.equal(lastTerminalRowIndex(sub.messages), 1);
  assert.equal(decideErrorRetry(sub, EMPTY), 'nudge');
  // No error shown but the last turn failed (the error was cleared): still a nudge.
  assert.equal(decideErrorRetry(bucket({ messages: [prompt('u1'), failure()] }), EMPTY), 'nudge');
});

test('E4 focus: an error that killed no turn, a finished turn, or no session at all only focuses the composer', () => {
  assert.equal(decideErrorRetry(bucket({ error: 'Network error', errorKilledTurn: false, messages: [prompt('u1'), failure()] }), EMPTY), 'focus');
  assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), reply(), success()] }), EMPTY), 'focus');
  assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [] }), EMPTY), 'focus');
  assert.equal(decideErrorRetry(undefined, EMPTY), 'focus');
  assert.equal(decideErrorRetry(undefined, DRAFT), 'focus');
  // Rows that are not human prompts after a success leave the turn finished: tool results, client echoes, meta rows,
  // synthetic rows and the /model command transcript.
  for (const row of [toolResult('u2'), prompt('client-123'), { ...prompt('u3'), isMeta: true }, { ...prompt('u4'), isSynthetic: true },
    prompt('u5', '<command-name>/model</command-name><command-args>opus</command-args>')]) {
    assert.equal(isHumanPromptRow(row), false, JSON.stringify(row));
    assert.equal(lastTurnFailed([prompt('u1'), success(), row]), false, JSON.stringify(row));
    assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), success(), row] }), EMPTY), 'focus');
  }
  assert.equal(isHumanPromptRow(prompt('u1')), true);
  assert.equal(isHumanPromptRow({ type: 'user', uuid: 'u1', message: { content: [{ type: 'text', text: 'Hello' }] } }), true);
});

test('E4 retry nudge copy: Try again (FazwRldA7z) and the canned continue texts, formatted through the host catalog', () => {
  assert.deepEqual(retryNudgeMessages.retryNudge, { defaultMessage: 'Try again', id: 'FazwRldA7z' });
  assert.equal(retryNudgeMessages.afterUsageLimit.id, 'UqWMzb4bJb');
  assert.equal(retryNudgeMessages.afterSleep.id, '4g6ivTtQ3C');
  const intl = { formatMessage: message => translate(message.defaultMessage) };
  assert.deepEqual(cannedNudges(intl).slice(3), ['Try again',
    'I hit my usage limit while you were working, but it has reset now. Please continue from where you left off.',
    'My computer went to sleep while you were working. Please continue from where you left off.']);
  setLocale('zh-CN');
  try {
    const canned = cannedNudges(intl);
    assert.equal(canned.length, 6);
    assert.equal(canned[0], '重试'); // zh-CN/common.mjs 'Try again'
    assert.equal(canned[3], 'Try again'); // the English originals stay in the list
  } finally {
    setLocale(DEFAULT_LOCALE);
  }
});
